    CONSTRAINT "FK_PlayerDailyLogins_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE
);

