    "PlayerQuestId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerProfileId" integer NOT NULL,
    "QuestId" integer NOT NULL,
    "Status" text NOT NULL,
    "Progress" integer NOT NULL,
    "TargetValue" integer NOT NULL,
    "AcceptedAt" timestamp with time zone NOT NULL,
    "CompletedAt" timestamp with time zone,
    "ClaimedAt" timestamp with time zone,
    CONSTRAINT "PK_PlayerQuests" PRIMARY KEY ("PlayerQuestId"),
    CONSTRAINT "FK_PlayerQuests_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE,
    CONSTRAINT "FK_PlayerQuests_Quests_QuestId" FOREIGN KEY ("QuestId") REFERENCES "Quests" ("QuestId") ON DELETE CASCADE
);

CREATE TABLE "PlayerSkills" (
    "PlayerSkillId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerProfileId" integer NOT NULL,
    "SkillId" integer NOT NULL,
    "Level" integer NOT NULL,
    "Experience" integer NOT NULL,
    "IsEquipped" boolean NOT NULL,
    "UnlockedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PlayerSkills" PRIMARY KEY ("PlayerSkillId"),
    CONSTRAINT "FK_PlayerSkills_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE,
    CONSTRAINT "FK_PlayerSkills_Skills_SkillId" FOREIGN KEY ("SkillId") REFERENCES "Skills" ("SkillId") ON DELETE CASCADE
);

CREATE TABLE "PlayerSkins" (
    "PlayerSkinId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerProfileId" integer NOT NULL,
    "SkinId" integer NOT NULL,
    "IsEquipped" boolean NOT NULL,
    "UnlockedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PlayerSkins" PRIMARY KEY ("PlayerSkinId"),
    CONSTRAINT "FK_PlayerSkins_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE,
    CONSTRAINT "FK_PlayerSkins_Skins_SkinId" FOREIGN KEY ("SkinId") REFERENCES "Skins" ("SkinId") ON DELETE CASCADE
);

CREATE TABLE "PlayerStats" (
    "PlayerStatId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerProfileId" integer NOT NULL,
    "CurrentHp" integer NOT NULL,
    "MaxHp" integer NOT NULL,
    "Atk" integer NOT NULL,
    "Def" integer NOT NULL,
    "MoveSpeed" integer NOT NULL,
    "AttackSpeed" integer NOT NULL,
    "CritRate" integer NOT NULL,
    "CritDamage" integer NOT NULL,
    "DamageBonus" integer NOT NULL,
    "SkillPoints" integer NOT NULL,
    "TotalWins" integer NOT NULL,
    "TotalLosses" integer NOT NULL,
    "TotalKills" integer NOT NULL,
    "TotalDeaths" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_PlayerStats" PRIMARY KEY ("PlayerStatId"),
    CONSTRAINT "FK_PlayerStats_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE
);

CREATE TABLE "PlayerStatsSnapshots" (
    "PlayerStatsSnapshotId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerProfileId" integer NOT NULL,
    "MaxHp" integer NOT NULL,
    "Atk" integer NOT NULL,
    "Def" integer NOT NULL,
    "MoveSpeed" integer NOT NULL,
    "AttackSpeed" integer NOT NULL,
    "CritRate" integer NOT NULL,
    "CritDamage" integer NOT NULL,
    "DamageBonus" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone,
    "RowVersion" bytea,
    CONSTRAINT "PK_PlayerStatsSnapshots" PRIMARY KEY ("PlayerStatsSnapshotId"),
    CONSTRAINT "FK_PlayerStatsSnapshots_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE
);

CREATE TABLE "PurchaseHistories" (
    "PurchaseHistoryId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerProfileId" integer NOT NULL,
    "ShopItemId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "TotalPrice" numeric NOT NULL,
    "PurchasedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PurchaseHistories" PRIMARY KEY ("PurchaseHistoryId"),
    CONSTRAINT "FK_PurchaseHistories_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE,
    CONSTRAINT "FK_PurchaseHistories_ShopItems_ShopItemId" FOREIGN KEY ("ShopItemId") REFERENCES "ShopItems" ("ShopItemId") ON DELETE CASCADE
);

CREATE TABLE "GuildInvitations" (
    "GuildInvitationId" integer GENERATED BY DEFAULT AS IDENTITY,
    "GuildId" integer NOT NULL,
    "InviterId" integer NOT NULL,
    "InviteeId" integer NOT NULL,
    "Status" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "RespondedAt" timestamp with time zone,
    CONSTRAINT "PK_GuildInvitations" PRIMARY KEY ("GuildInvitationId"),
    CONSTRAINT "FK_GuildInvitations_Guilds_GuildId" FOREIGN KEY ("GuildId") REFERENCES "Guilds" ("GuildId") ON DELETE CASCADE,
    CONSTRAINT "FK_GuildInvitations_PlayerProfiles_InviteeId" FOREIGN KEY ("InviteeId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE,
    CONSTRAINT "FK_GuildInvitations_PlayerProfiles_InviterId" FOREIGN KEY ("InviterId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE
);

CREATE TABLE "GuildMembers" (
    "GuildMemberId" integer GENERATED BY DEFAULT AS IDENTITY,
    "GuildId" integer NOT NULL,
    "PlayerProfileId" integer NOT NULL,
    "Role" text NOT NULL,
    "Contribution" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "JoinedAt" timestamp with time zone NOT NULL,
    "LeftAt" timestamp with time zone,
    CONSTRAINT "PK_GuildMembers" PRIMARY KEY ("GuildMemberId"),
    CONSTRAINT "FK_GuildMembers_Guilds_GuildId" FOREIGN KEY ("GuildId") REFERENCES "Guilds" ("GuildId") ON DELETE CASCADE,
    CONSTRAINT "FK_GuildMembers_PlayerProfiles_PlayerProfileId" FOREIGN KEY ("PlayerProfileId") REFERENCES "PlayerProfiles" ("PlayerProfileId") ON DELETE CASCADE
);

